"use client"

import { getOrCreateAnonymousId } from "@/lib/anonymous-id"
import { useAudioRoom } from "@/hooks/use-audio-room"
import { AnimatePresence, motion } from "framer-motion"
import { Heart, Loader2, Mic, MicOff, Sparkles } from "lucide-react"
import { useCallback, useEffect, useMemo, useState } from "react"

interface TwinCandidate {
  id: string
  anonymous_id: string
  words: string
  source_type: string
}

interface TwinMatch {
  id: string
  room_id: string
  expires_at: string
}

interface FindYourTwinProps {
  sourceType?: "echo" | "session"
  sourceId?: string | null
  textSeed?: string
  compact?: boolean
}

export function FindYourTwin({
  sourceType = "session",
  sourceId = null,
  textSeed = "quiet present human",
  compact = false,
}: FindYourTwinProps) {
  const [anonymousId, setAnonymousId] = useState("")
  const [candidates, setCandidates] = useState<TwinCandidate[]>([])
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const [match, setMatch] = useState<TwinMatch | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [message, setMessage] = useState("")
  const [timeLeft, setTimeLeft] = useState(14 * 60)

  const roomName = match?.room_id || "unmute-twin-waiting"
  const participantName = useMemo(
    () => (anonymousId ? `twin-${anonymousId.slice(-8)}` : "anonymous"),
    [anonymousId]
  )

  const {
    isConnected,
    isConnecting,
    isMuted,
    audioEnabled,
    error: audioError,
    connect,
    toggleMute,
  } = useAudioRoom(roomName, participantName)

  const loadCandidates = useCallback(async (id: string) => {
    setIsLoading(true)
    setMessage("")

    const matchResponse = await fetch(`/api/twin/match?anonymousId=${encodeURIComponent(id)}`)
    const matchData = await matchResponse.json()
    if (matchResponse.ok && matchData.match) {
      setMatch(matchData.match)
      setMessage("You found your twin. You have 14 minutes. Go in.")
      setIsLoading(false)
      return
    }

    await fetch("/api/twin/candidates", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ anonymousId: id, sourceType, sourceId, textSeed }),
    })

    const response = await fetch(`/api/twin/candidates?anonymousId=${encodeURIComponent(id)}`)
    const data = await response.json()

    if (!response.ok) {
      setMessage(data.error || "Twin cards are quiet right now.")
      setCandidates([])
    } else {
      setCandidates(data.candidates || [])
      if (!data.candidates?.length) {
        setMessage("No matching Echoes yet. Come back tomorrow.")
      }
    }

    setIsLoading(false)
  }, [sourceId, sourceType, textSeed])

  useEffect(() => {
    if (!anonymousId || !selectedId || match) return

    const interval = window.setInterval(async () => {
      const response = await fetch(`/api/twin/match?anonymousId=${encodeURIComponent(anonymousId)}`)
      const data = await response.json()
      if (response.ok && data.match) {
        setMatch(data.match)
        setMessage("You found your twin. You have 14 minutes. Go in.")
      }
    }, 4000)

    return () => window.clearInterval(interval)
  }, [anonymousId, match, selectedId])

  useEffect(() => {
    const id = getOrCreateAnonymousId()
    setAnonymousId(id)
    loadCandidates(id)
  }, [loadCandidates])

  useEffect(() => {
    if (!match) return

    const tick = () => {
      const remaining = Math.max(0, Math.floor((new Date(match.expires_at).getTime() - Date.now()) / 1000))
      setTimeLeft(remaining)
    }

    tick()
    const interval = window.setInterval(tick, 1000)
    return () => window.clearInterval(interval)
  }, [match])

  const handleChooseTwin = async (candidate: TwinCandidate) => {
    setSelectedId(candidate.anonymous_id)
    setMessage("")

    const response = await fetch("/api/twin/like", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        anonymousId,
        likedAnonymousId: candidate.anonymous_id,
      }),
    })
    const data = await response.json()

    if (!response.ok) {
      setMessage(data.error || "That resonance did not land. Try again.")
      setSelectedId(null)
      return
    }

    if (data.matched) {
      setMatch(data.match)
      setMessage("You found your twin. You have 14 minutes. Go in.")
    } else {
      setMessage("If they feel it too, this room will open. Come back tomorrow.")
    }
  }

  const minutes = Math.floor(timeLeft / 60)
  const seconds = String(timeLeft % 60).padStart(2, "0")

  return (
    <section
      className={`w-full ${compact ? "" : "min-h-screen px-4 py-24"} bg-background text-foreground`}
      aria-label="Find Your Twin"
    >
      <div className="mx-auto w-full max-w-3xl">
        <motion.div
          initial={{ opacity: 0, y: 18 }}
          animate={{ opacity: 1, y: 0 }}
          className="rounded-2xl border border-border/70 bg-card/50 p-5 shadow-[0_0_40px_rgba(255,255,255,0.04)] sm:p-8"
        >
          <div className="mb-6 flex items-start justify-between gap-4">
            <div>
              <p className="mb-2 text-xs uppercase tracking-[0.22em] text-muted-foreground">Find Your Twin</p>
              <h2 className="text-2xl font-light leading-tight text-foreground sm:text-3xl">
                Want to find someone who feels like you do today?
              </h2>
            </div>
            <div className="rounded-full border border-amber-300/20 bg-amber-300/10 p-3 text-amber-200">
              <Sparkles className="h-5 w-5" aria-hidden="true" />
            </div>
          </div>

          <AnimatePresence mode="wait">
            {match ? (
              <motion.div
                key="match"
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                className="space-y-5 text-center"
              >
                <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full border border-amber-300/30 bg-amber-300/10 text-amber-200">
                  <Heart className="h-7 w-7 fill-current" aria-hidden="true" />
                </div>
                <div>
                  <p className="text-xl font-light text-foreground">You found your twin.</p>
                  <p className="mt-2 text-sm text-muted-foreground">You have {minutes}:{seconds}. Go in gently.</p>
                </div>
                <button
                  onClick={isConnected ? toggleMute : connect}
                  disabled={isConnecting || timeLeft <= 0}
                  className="mx-auto flex h-16 w-16 items-center justify-center rounded-full border border-amber-300/30 bg-amber-300 text-background transition hover:scale-105 disabled:opacity-50"
                  aria-label={isConnected && !isMuted ? "Mute microphone" : "Join twin audio room"}
                >
                  {isConnecting ? (
                    <Loader2 className="h-6 w-6 animate-spin" aria-hidden="true" />
                  ) : isConnected && !isMuted ? (
                    <Mic className="h-6 w-6" aria-hidden="true" />
                  ) : (
                    <MicOff className="h-6 w-6" aria-hidden="true" />
                  )}
                </button>
                {!audioEnabled && audioError && (
                  <p className="text-xs text-muted-foreground">Audio is not configured yet for this room.</p>
                )}
              </motion.div>
            ) : (
              <motion.div key="cards" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                {isLoading ? (
                  <div className="flex items-center justify-center gap-3 py-12 text-sm text-muted-foreground">
                    <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" />
                    Listening for quiet matches
                  </div>
                ) : (
                  <div className="grid gap-3 sm:grid-cols-3">
                    {candidates.map((candidate, index) => (
                      <motion.button
                        key={candidate.id}
                        initial={{ opacity: 0, y: 16 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: index * 0.08 }}
                        onClick={() => handleChooseTwin(candidate)}
                        disabled={!!selectedId}
                        className="min-h-40 rounded-2xl border border-border bg-background/70 p-5 text-left transition hover:-translate-y-1 hover:border-amber-200/40 hover:bg-secondary/60 disabled:cursor-default disabled:opacity-60"
                      >
                        <p className="mb-8 text-sm leading-relaxed text-muted-foreground">Three words they left behind</p>
                        <p className="text-xl font-light leading-snug text-foreground">{candidate.words}</p>
                        <span className="mt-8 inline-flex items-center gap-2 text-sm text-amber-200">
                          <Heart className="h-4 w-4" aria-hidden="true" />
                          I feel this too
                        </span>
                      </motion.button>
                    ))}
                  </div>
                )}
                {message && <p className="mt-5 text-center text-sm text-muted-foreground">{message}</p>}
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>
      </div>
    </section>
  )
}
